<template>
  <main class="review-page" :class="{ archived: isArchive }" v-loading="loading" @click="handleArchiveAction">
    <header class="event-context"><div class="event-main"><span class="event-badge"><el-icon><Trophy /></el-icon></span><strong>{{ tournament.name || '当前赛事' }}</strong><el-tag type="primary" effect="plain">{{ divisionName }}</el-tag><el-tag type="success" effect="plain">进行中</el-tag><span><el-icon><Calendar /></el-icon>{{ eventDateText }}</span><span><el-icon><LocationInformation /></el-icon>{{ tournament.province || tournament.location || '举办地待定' }}</span></div><el-button plain @click="router.push('/tournament-space')"><el-icon><SwitchButton /></el-icon>返回赛事空间</el-button></header>
    <section class="workspace">
      <header class="page-title"><h1>{{ isArchive ? '赛果管理' : '比赛管理' }} / {{ divisionName }} / {{ isArchive ? '比赛归档详情' : '赛果复核与归档' }}</h1><el-button plain @click="backToList"><el-icon><ArrowLeft /></el-icon>{{ isArchive ? '返回赛果管理' : `返回${divisionName}比赛列表` }}</el-button></header>
      <el-alert v-if="substitutionWarnings.length" type="warning" :closable="false" show-icon :title="`换人记录存在 ${substitutionWarnings.length} 项异常`" :description="substitutionWarnings.map(item => `${item.minute}′：${item.message}`).join('；')" />
      <section v-if="isProfessionalReview && !isArchive" class="professional-review"><el-alert title="比赛状态：裁判已提交 · 待主办方复核" type="warning" :closable="false" show-icon/><section class="pro-score"><div><small>场序</small><b>{{ match.matchSequence }}</b></div><div><small>日期时间</small><b>{{ matchDateText }}</b></div><div><small>比赛场地</small><b>{{ match.venue }}</b></div><strong>{{ homeName }}　{{ match.homeScore }} : {{ match.awayScore }}　{{ awayName }}</strong><div><small>主裁判</small><b>{{ mainRefereeName }}</b></div><div><small>提交时间</small><b>{{ submittedAtText }}</b></div></section><nav class="professional-review-tabs"><span class="active">赛果概览</span><span>事件流水</span><span>裁判报告</span><span>电子比赛记录</span><span>签字与确认</span></nav><section class="pro-evidence"><article><h2>双方阵容快照（已上报）</h2><div class="pro-team"><b>{{ homeName }}</b><span>首发 11 人　替补 7 人　本方总计 18 人</span><el-button plain size="small">查看详情</el-button></div><div class="pro-team"><b>{{ awayName }}</b><span>首发 11 人　替补 6 人　本方总计 17 人</span><el-button plain size="small">查看详情</el-button></div><h2>裁判团队</h2><p>主裁判　{{ mainRefereeName }}　　第一助理裁判　李明</p><p>第二助理裁判　张伟　　第四官员　赵磊</p></article><article><h2>完整事件流水（共 {{ sortedEvents.length }} 条）</h2><div v-for="event in sortedEvents" :key="`pro-${event._id}`" class="pro-event"><b>{{ event.minute }}′</b><span>{{ event.teamName }}</span><strong>{{ event.playerName }}</strong><em>{{ eventLabel(event) }}　{{ event.score }}</em></div><el-button plain>查看完整事件</el-button></article><article><h2>裁判报告（已上报）</h2><p>比赛结果　{{ homeName }} {{ match.homeScore }} : {{ match.awayScore }} {{ awayName }}</p><p>公平竞赛　良好</p><p>情况说明　无重大情况</p><el-button plain>查看完整报告</el-button><h2>电子比赛记录（已生成）</h2><p>记录状态　已生成（共 {{ sortedEvents.length }} 条事件）</p><el-button plain>查看电子比赛记录</el-button><h2>签字与确认（已完成）</h2><p>主裁判签字　已签字　　双方球队　已确认</p></article></section><footer class="pro-actions"><el-button type="warning" plain @click="openReturnDialog">退回裁判修正</el-button><el-button type="success" :loading="saving" @click="archiveRecord">确认无误并归档</el-button><el-button link>异常纠错（需说明并留痕）</el-button></footer></section>
      <section v-if="isArchive" class="archive-workspace"><div class="archive-head"><div class="archive-match"><div><small>场序</small><b>{{ match.matchSequence }}</b><span>{{ matchDateText }} · {{ match.venue }}</span></div><strong>{{ homeName }}　<span>{{ match.homeScore }} : {{ match.awayScore }}</span>　{{ awayName }}</strong><footer>归档编号：ARC-{{ match.matchSequence }}　　复核人：{{ mainRefereeName }}　　归档时间：{{ submittedAtText }}</footer></div><aside><h2>复核结论</h2><b><el-icon><CircleCheckFilled /></el-icon> 合规归档</b><p>经复核，本场比赛数据完整、记录规范，满足归档要求。</p></aside></div><section class="archive-evidence"><article><h2>双方阵容快照（合计 36 人）</h2><div class="roster-snapshot"><b>{{ homeName }}（18人）</b><p>首发阵容 11 人　替补球员 7 人</p><p>1号 守门员　2号 后卫　7号 张浩　9号 王磊　10号 刘洋</p></div><div class="roster-snapshot"><b>{{ awayName }}（18人）</b><p>首发阵容 11 人　替补球员 7 人</p><p>1号 守门员　3号 后卫　8号 李强　11号 陈凯　16号 赵宇</p></div></article><article><h2>比赛事件时间轴</h2><div v-for="event in sortedEvents" :key="`archive-${event._id}`" class="archive-event"><b>{{ event.minute }}'</b><span>{{ eventLabel(event) }}</span><strong>{{ event.teamName }}　{{ event.playerName }}</strong><em>{{ event.score }}</em></div></article><article><h2>裁判报告（摘要）</h2><p>比赛整体情况良好，双方队员遵守规则，团结竞赛。</p><ul><li>比赛结果：{{ homeName }} {{ match.homeScore }} : {{ match.awayScore }} {{ awayName }}</li><li>比赛时长：上下半场各 40 分钟</li><li>纪律情况：双方黄牌各 1 张，无红牌</li><li>主裁判签字：{{ mainRefereeName }}</li></ul></article></section><section class="archive-footprint"><article><h2>电子记录</h2><p>比赛记录表　<span>已归档</span></p><p>事件记录表　<span>已归档</span></p><p>阵容名单表　<span>已归档</span></p></article><article><h2>签字确认</h2><p>主裁判：{{ mainRefereeName }}　<span>已签字</span></p><p>{{ homeName }}　<span>已确认</span></p><p>{{ awayName }}　<span>已确认</span></p></article><article><h2>审计摘要</h2><p>提交复核　{{ submittedAtText }}</p><p>复核通过　{{ submittedAtText }}</p><p>完成归档　{{ submittedAtText }}</p><p v-if="match.resultCorrection">异常纠错　{{ formatDate(match.resultCorrection.correctedAt || match.resultCorrectedAt) }} <span>已留痕</span></p><p v-if="match.resultCorrection">纠错原因　{{ match.resultCorrection.reason }}</p></article></section><footer class="archive-actions"><el-button type="warning" plain @click="openScoreCorrection"><el-icon><EditPen /></el-icon>异常纠错</el-button><el-button plain @click="exportElectronicReport"><el-icon><Document /></el-icon>下载电子裁判报告</el-button><el-button plain>查看审计日志</el-button><el-button plain @click="backToList"><el-icon><ArrowLeft /></el-icon>返回比赛列表</el-button></footer></section>
      <nav v-if="!isArchive && !isProfessionalReview" class="review-steps" aria-label="赛果复核状态"><span class="done"><b><el-icon><CircleCheckFilled /></el-icon></b>裁判提交完成</span><i></i><span class="active"><b>2</b>主办方复核</span><i></i><span><b>3</b>资料复核</span><i></i><span><b>4</b>完成归档</span></nav>
      <el-alert v-if="isArchive" class="archive-alert" title="本场比赛已归档：现场快照和裁判原始记录只读；比分如需更正，请走异常纠错并填写原因。" type="success" :closable="false" show-icon />
      <section v-if="!isProfessionalReview || isArchive" class="match-meta"><div><el-icon><Tickets /></el-icon><span>场序<b>{{ match.matchSequence || '—' }}</b></span></div><div><el-icon><Calendar /></el-icon><span>比赛时间<b>{{ matchDateText }}</b></span></div><div><el-icon><LocationInformation /></el-icon><span>比赛场地<b>{{ match.venue || '待定' }}</b></span></div><div><el-icon><Medal /></el-icon><span>赛事组别<b>{{ divisionName }}杯赛</b></span></div><div><span>比赛状态<b class="online"><i></i>{{ matchStatusLabel }}</b></span></div><el-tag :type="refereeRecordSubmitted ? 'success' : 'info'" effect="plain"><el-icon><CircleCheckFilled /></el-icon>{{ refereeRecordSubmitted ? '裁判记录已提交' : '裁判记录未提交' }}</el-tag></section>
      <section v-if="!isProfessionalReview || isArchive" class="score-card"><div class="team home"><span class="crest"><img v-if="homeLogo" :src="homeLogo" alt="" /><b v-else>{{ teamInitial(homeName) }}</b></span><strong>{{ homeName }}</strong></div><div class="score"><b>{{ match.homeScore ?? '—' }}</b><em>:</em><b>{{ match.awayScore ?? '—' }}</b><small>来源：{{ recordSourceLabel }}</small></div><div class="team away"><strong>{{ awayName }}</strong><span class="crest"><img v-if="awayLogo" :src="awayLogo" alt="" /><b v-else>{{ teamInitial(awayName) }}</b></span></div><footer><span>提交人：{{ mainRefereeName }}</span><span>提交时间：{{ submittedAtText }}</span><el-button plain size="small" @click="showOriginal=true">查看原始提交记录</el-button></footer></section>
      <section v-if="!isProfessionalReview || isArchive" class="review-grid"><article class="panel"><h2>裁判提交内容</h2><div class="score-row"><span>最终比分</span><b>{{ match.homeScore ?? '—' }}　:　{{ match.awayScore ?? '—' }}</b></div><div class="event-title"><span>事件记录（人工事件）</span><b>共 {{ sortedEvents.length }} 条</b></div><div v-for="event in sortedEvents" :key="event._id" class="event-row"><b>{{ event.minute }}′</b><span>{{ event.teamName }}</span><span>{{ eventLabel(event) }}</span><span>{{ event.playerName }}</span><em>（手工）</em></div><div class="note"><strong>事件说明</strong><p>事件记录仅为文字记录，不生成球员个人统计。</p></div><div class="status-row"><span>比赛状态</span><b>正常结束</b></div><footer><el-icon><InfoFilled /></el-icon>说明：以上为裁判通过服务号提交的内容，仅为人工填写信息，不生成球员个人统计数据。</footer></article>
        <article class="panel organizer-panel"><h2>主办方复核</h2><div class="check-row"><span>比分核对</span><b class="ok"><el-icon><CircleCheckFilled /></el-icon>无误</b></div><div class="check-row"><span>事件记录</span><b>仅作文字记录</b></div><div class="check-row"><span>异常情况</span><b>正常</b></div><label>复核意见（必填）<el-input v-model="reviewNote" type="textarea" :rows="4" maxlength="200" show-word-limit placeholder="请填写复核意见（如有），若无异常可填写“无”。" /></label><el-button type="success" plain @click="openReturnDialog">发起资料复核</el-button><footer><el-icon><InfoFilled /></el-icon>如发现错误，请发起资料复核并退回，系统将记录修改前后内容。</footer></article>
        <article class="panel materials-panel"><header><h2>比赛资料归档</h2><div class="materials-heading-actions"><el-tag type="primary" effect="plain">三类资料 {{ materialSubmittedCount }}/3</el-tag><el-button v-if="!isArchive" type="primary" plain size="small" @click="openSupplementPage">上传复核文件</el-button></div></header><div v-for="item in materialRows" :key="item.label" class="material-row"><div><strong>{{ item.label }}</strong><b :class="{ 'material-pending': !item.submitted }">{{ item.status }}</b></div><span class="paper"><el-icon><Document /></el-icon></span><div class="material-actions"><el-button plain size="small" :disabled="!item.submitted" @click="openSupplementPage">查看</el-button><el-button plain size="small" @click="openSupplementPage">{{ item.submitted ? '补充修正' : '补交资料' }}</el-button></div></div><footer><el-icon><InfoFilled /></el-icon>说明：{{ materialSubmittedCount ? '已提交资料可供复核，未提交项需补交。' : '当前尚未收到比赛资料提交。' }}</footer></article></section>
      <footer v-if="!isProfessionalReview || isArchive" class="review-actions"><p><el-icon><InfoFilled /></el-icon>审计提示：裁判原始提交永久保留，更正需填写原因并记录修改前后内容。</p><el-button size="large" @click="saveDraft">保存复核草稿</el-button><el-button type="success" size="large" :loading="saving" @click="archiveRecord">复核通过并完成归档</el-button></footer>
    <section v-if="!isProfessionalReview || isArchive" class="verification-overview">
      <article class="verification-panel lineup-panel"><header><div><h2>双方首发与替补</h2><small>出场次数与出场时间按本场事件核算 · 比赛时长 {{ matchDurationMinutes }}′</small></div><div class="panel-header-actions"><el-tag type="success" effect="plain">{{ lineupPanels.filter(item => item.submitted).length }}/2 已提交</el-tag><el-button size="small" plain @click="exportLineupList">下载首发名单</el-button></div></header><div class="lineup-side-grid"><section v-for="item in lineupPanels" :key="item.side" class="verification-team"><div class="team-panel-heading"><strong>{{ item.teamName }}</strong><el-tag size="small" :type="item.submitted ? 'success' : 'warning'">{{ item.status }}</el-tag></div><p>首发 {{ item.starters }} 人 · 替补 {{ item.substitutes }} 人 · 已出场 {{ item.appearanceCount }} 人 · 累计 {{ item.totalMinutes }}′</p><table class="lineup-table"><thead><tr><th>名单</th><th>号码</th><th>球衣名</th><th>球员</th><th>年龄</th><th>位置</th><th>出场次数</th><th>出场时间</th></tr></thead><tbody><tr v-for="player in item.players" :key="`${item.side}-${player.key}`"><td><span :class="['role-badge', player.role]">{{ player.role === 'starter' ? '首发' : '替补' }}</span></td><td>{{ player.jerseyNumber }}</td><td>{{ player.jerseyName }}</td><td>{{ player.name }}</td><td>{{ player.age }}</td><td>{{ player.position }}</td><td>{{ player.appearances }}</td><td>{{ player.minutes }}′</td></tr><tr v-if="!item.players.length"><td colspan="8" class="verification-empty">暂无名单快照</td></tr></tbody></table></section></div></article>
      <article class="verification-panel event-panel"><header><div><h2>比赛事件</h2><small>按主队、客队分别核验</small></div><span>共 {{ sortedEvents.length }} 条</span></header><div class="event-stat-row"><span><b>{{ eventStats.goals }}</b>进球</span><span><b>{{ eventStats.substitutions }}</b>换人</span><span><b>{{ eventStats.yellow }}</b>黄牌</span><span><b>{{ eventStats.red }}</b>红牌</span></div><div class="event-side-grid"><section v-for="panel in eventPanels" :key="panel.side" class="event-side"><h3>{{ panel.teamName }}</h3><section class="event-group"><h4>进球 <small>{{ panel.goals.length }} 条</small></h4><div v-for="event in panel.goals" :key="`goal-${panel.side}-${event._id}`" class="event-group-row"><b>{{ event.minute }}′</b><span>{{ event.playerName || '球员待定' }}</span><em>{{ event.score || '' }}</em></div><p v-if="!panel.goals.length" class="verification-empty">暂无进球记录</p></section><section class="event-group"><h4>换人 <small>{{ panel.substitutions.length }} 条</small></h4><div v-for="event in panel.substitutions" :key="`sub-${panel.side}-${event._id}`" class="event-group-row substitution-row"><b>{{ event.minute }}′</b><span class="substitution-pair"><span class="swap-line swap-out"><i class="swap-arrow">↓</i><small>换下</small>{{ event.outgoing || '球员待核对' }}</span><span class="swap-line swap-in"><i class="swap-arrow">↑</i><small>换上</small>{{ event.incoming || '球员待核对' }}</span></span><em>换人</em></div><p v-if="!panel.substitutions.length" class="verification-empty">暂无换人记录</p></section><section class="event-group"><h4>红黄牌 <small>{{ panel.cards.length }} 条</small></h4><div v-for="event in panel.cards" :key="`card-${panel.side}-${event._id}`" class="event-group-row"><b>{{ event.minute }}′</b><span>{{ event.playerName || '球员待定' }}</span><em>{{ eventLabel(event) }}</em></div><p v-if="!panel.cards.length" class="verification-empty">暂无红黄牌记录</p></section></section></div></article>
      <article class="verification-panel discipline-panel"><header><h2>纪律与停赛</h2><el-tag type="warning" effect="plain">按规程确认</el-tag></header><div v-for="item in disciplineRows" :key="item.key" class="discipline-row"><span>{{ item.teamName }}</span><strong>{{ item.playerName }}</strong><em>{{ item.notice }}</em></div><p v-if="!disciplineRows.length" class="verification-empty">暂无红黄牌或停赛提醒</p><footer>红牌、累计黄牌是否停赛，以赛事纪律规则最终确认。</footer></article>
      <article class="verification-panel report-panel"><header><div><h2>比赛报告存档</h2><small>{{ manualSupplement ? '主办方补录报告' : '四官电子裁判报告' }}</small></div><el-tag :type="reportSubmitted ? 'success' : 'warning'" effect="plain">{{ reportSubmitted ? '已提交' : '未上传' }}</el-tag></header><div class="report-archive-content"><div class="report-mode"><span>资料来源</span><strong>{{ reportModeLabel }}</strong><small>{{ manualSupplement ? '补录比分必须留存 1–2 张纸质比赛报告' : '上传资料与生成电子报告分开管理' }}</small></div><div class="report-file-list"><div v-for="(file,index) in reportFiles" :key="file.fileId || file.url || index" class="report-file-row"><el-icon><Document /></el-icon><span>{{ file.name || `比赛报告 ${index+1}` }}</span><small>{{ file.sizeText || '' }}</small><el-button link size="small" @click="viewReportFile(file)">查看</el-button></div><p v-if="!reportFiles.length" class="verification-empty">暂无裁判报告存档</p></div></div><div class="report-actions"><input ref="reportUploadInput" type="file" accept="image/*,.pdf" multiple hidden @change="onReportFilesSelected" /><el-button type="success" plain :loading="reportUploading" @click="triggerReportUpload">{{ reportSubmitted ? '继续上传报告' : '上传裁判报告' }}</el-button><el-button v-if="!manualSupplement" type="primary" plain @click="openReportPreview">生成比赛报告</el-button><el-button plain @click="exportLineupList">预览首发名单</el-button></div></article>
    </section>
    </section>
    <div ref="cslExportTemplate" class="csl-export-wrap" aria-hidden="true"><div class="csl-export-page"><h1>{{ tournament.name || '足球赛事' }}</h1><h2>首发名单</h2><div class="csl-export-meta"><span>主队：{{ homeName }}</span><span>客队：{{ awayName }}</span><span>场序：{{ match.matchSequence || '—' }}</span><span>日期：{{ matchDateText }}</span><span>场地：{{ match.venue || '待定' }}</span></div><div class="csl-export-section"><h3>首发球员</h3><div class="csl-export-columns"><table v-for="item in lineupPanels" :key="`pdf-starter-${item.side}`"><thead><tr><th colspan="8">{{ item.teamName }}</th></tr><tr><th>号码</th><th>位置</th><th>姓名</th><th>球衣名</th><th>年龄</th><th>出场次数</th><th>出场时间</th><th>状态</th></tr></thead><tbody><tr v-for="player in item.players.filter(row => row.role === 'starter')" :key="`pdf-${item.side}-starter-${player.key}`"><td>{{ player.jerseyNumber }}</td><td>{{ player.position }}</td><td>{{ player.name }}</td><td>{{ player.jerseyName }}</td><td>{{ player.age }}</td><td>{{ player.appearances }}</td><td>{{ player.minutes }}′</td><td>首发</td></tr><tr v-if="!item.players.filter(row => row.role === 'starter').length"><td colspan="8">暂无首发名单</td></tr></tbody></table></div></div><div class="csl-export-section"><h3>替补球员</h3><div class="csl-export-columns"><table v-for="item in lineupPanels" :key="`pdf-sub-${item.side}`"><thead><tr><th colspan="8">{{ item.teamName }}</th></tr><tr><th>号码</th><th>位置</th><th>姓名</th><th>球衣名</th><th>年龄</th><th>出场次数</th><th>出场时间</th><th>状态</th></tr></thead><tbody><tr v-for="player in item.players.filter(row => row.role === 'substitute')" :key="`pdf-${item.side}-sub-${player.key}`"><td>{{ player.jerseyNumber }}</td><td>{{ player.position }}</td><td>{{ player.name }}</td><td>{{ player.jerseyName }}</td><td>{{ player.age }}</td><td>{{ player.appearances }}</td><td>{{ player.minutes }}′</td><td>替补</td></tr><tr v-if="!item.players.filter(row => row.role === 'substitute').length"><td colspan="8">暂无替补名单</td></tr></tbody></table></div></div><footer>数据来源：本场比赛阵容快照与事件核验　生成时间：{{ formatDate(new Date()) }}</footer></div></div>
    <el-dialog v-model="lineupPreviewVisible" title="预览首发名单（中超模板）" width="920px"><div class="lineup-preview-dialog"><img v-if="lineupPreviewImage" :src="lineupPreviewImage" alt="首发名单预览" /><el-empty v-else description="正在生成预览" /></div><template #footer><el-button @click="lineupPreviewVisible=false">关闭</el-button><el-button type="primary" @click="downloadLineupPDF">下载 PDF</el-button></template></el-dialog>
