const lineupPanels=computed(()=>['home','away'].map(side=>{const lineup=lineupFor(side);const starters=Array.isArray(lineup.starters)?lineup.starters:(Array.isArray(lineup.players)?lineup.players.filter(item=>item?.role!=='substitute'):[]);const substitutes=Array.isArray(lineup.substitutes)?lineup.substitutes:(Array.isArray(lineup.players)?lineup.players.filter(item=>item?.role==='substitute'):[]);const submitted=submittedLineup(lineup);const players=[...starters.map((item,index)=>lineupRow(item,'starter',index,side)),...substitutes.map((item,index)=>lineupRow(item,'substitute',index,side))];const findPlayer=name=>{const target=cleanPlayerName(name);return players.find(item=>item.name===name||item.plainName===target||item.name.includes(name)||item.plainName.includes(target))};substitutionEvents.value.filter(event=>eventSide(event)===side).forEach(event=>{const swap=swapNames(event);const incoming=findPlayer(swap.incoming);const outgoing=findPlayer(swap.outgoing);if(outgoing){outgoing.appearances=Math.max(1,outgoing.appearances);outgoing.minutes=Math.min(outgoing.minutes||matchDurationMinutes.value,Number(event.minute)||0)}if(incoming){incoming.appearances=Math.max(1,incoming.appearances);incoming.minutes=Math.max(0,matchDurationMinutes.value-(Number(event.minute)||0))}});return {side,teamName:side==='home'?homeName.value:awayName.value,submitted,status:submitted?'已提交':'未提交',starters:starters.length,substitutes:substitutes.length,players,starterList:players.filter(item=>item.role==='starter').map(item=>item.name),substituteList:players.filter(item=>item.role==='substitute').map(item=>item.name),appearanceCount:players.filter(item=>item.appearances>0).length,totalMinutes:players.reduce((sum,item)=>sum+item.minutes,0),preview:players.slice(0,5).map(item=>item.name).join('　')}}))
const eventStats=computed(()=>sortedEvents.value.reduce((stats,event)=>{const type=String(event.type||'').toLowerCase();if(type==='goal')stats.goals++;if(type==='substitution')stats.substitutions++;const cards=cardEventCounts(event);stats.yellow+=cards.yellow;stats.red+=cards.red;return stats},{goals:0,substitutions:0,yellow:0,red:0}))
const goalEvents=computed(()=>sortedEvents.value.filter(item=>String(item.type||'').toLowerCase()==='goal'))
const substitutionEvents=computed(()=>sortedEvents.value.filter(item=>String(item.type||'').toLowerCase()==='substitution').map(event=>({...event,...swapNames(event),teamName:event.teamName||homeName.value})))
const cardEvents=computed(()=>sortedEvents.value.filter(item=>['yellow_card','red_card'].includes(String(item.type||'').toLowerCase())||isSecondYellowRed(item)))
function numberForName(name,side){const target=cleanPlayerName(name);return lineupPanels.value.find(item=>item.side===side)?.players.find(player=>player.plainName===target||player.name===name)?.jerseyNumber||''}
const eventPanels=computed(()=>['home','away'].map(side=>{const teamName=side==='home'?homeName.value:awayName.value;const decorate=event=>{const number=event.playerNumber||numberForName(event.playerName,side);return {...event,teamName:event.teamName||teamName,playerName:number&&event.playerName&&!String(event.playerName).includes(String(number))?`${number}号 ${event.playerName}`:event.playerName}};const substitutions=substitutionEvents.value.filter(event=>eventSide(event)===side).map(event=>{const swap=swapNames(event);const incomingNumber=event.incomingPlayerNumber||numberForName(swap.incoming,side);const outgoingNumber=event.outgoingPlayerNumber||numberForName(swap.outgoing,side);return {...event,teamName:event.teamName||teamName,incoming:incomingNumber&&swap.incoming&&!String(swap.incoming).includes(String(incomingNumber))?`${incomingNumber}号 ${swap.incoming}`:swap.incoming,outgoing:outgoingNumber&&swap.outgoing&&!String(swap.outgoing).includes(String(outgoingNumber))?`${outgoingNumber}号 ${swap.outgoing}`:swap.outgoing,incomingNumber,outgoingNumber}});return {side,teamName,goals:goalEvents.value.filter(event=>eventSide(event)===side).map(decorate),substitutions,cards:cardEvents.value.filter(event=>eventSide(event)===side).map(decorate)}}))
const disciplineRows=computed(()=>{const rows=[];const notices=Array.isArray(match.value.suspensionNotices)?match.value.suspensionNotices:[];notices.forEach((item,index)=>rows.push({key:`notice-${index}`,teamName:item.teamName||'球队待定',playerName:item.playerName||'球员待定',notice:item.notice||item.reason||'停赛提醒'}));const cards={};sortedEvents.value.filter(event=>['yellow_card','red_card'].includes(String(event.type||'').toLowerCase())||isSecondYellowRed(event)).forEach(event=>{const key=`${event.teamName||''}:${event.playerName||''}`;const row=cards[key]||(cards[key]={key,teamName:event.teamName||'球队待定',playerName:event.playerName||'球员待定',yellow:0,red:0});const counts=cardEventCounts(event);row.yellow+=counts.yellow;row.red+=counts.red});Object.values(cards).forEach(row=>{if(row.red||row.yellow>=2)rows.push({key:`card-${row.key}`,teamName:row.teamName,playerName:row.playerName,notice:row.red?'红牌，停赛待确认':'累计黄牌，停赛待确认'})});return rows})
const reportModeLabel=computed(()=>manualSupplement.value?'主办方补录报告':'电子裁判报告')
const reportActionLabel=computed(()=>manualSupplement.value?'上传比赛报告（1–2张）':'上传电子裁判报告')
const reportFiles=computed(()=>Array.isArray(match.value.organizerSupplementFiles)?match.value.organizerSupplementFiles:[])
const eventDateText=computed(()=>{const f=v=>{const d=new Date(v?.$date||v);return Number.isNaN(d.getTime())?'':`${d.getFullYear()}.${String(d.getMonth()+1).padStart(2,'0')}.${String(d.getDate()).padStart(2,'0')}`};const a=f(tournament.value.startDate),b=f(tournament.value.endDate);return a&&b?`${a}—${b}`:a||b||'日期待定'})
function team(id){return teams.value.find(item=>item._id===id||item.id===id)}function teamInitial(name){return Array.from(name||'?')[0]||'?'}function eventLabel(event){return({goal:'进球',yellow_card:'黄牌',red_card:'红牌',second_yellow_red:'2黄变1红',substitution:'换人'}[event.type]||'比赛事件')}function formatDate(value){if(!value)return'';const date=new Date(value?.$date||value);return Number.isNaN(date.getTime())?String(value):date.toLocaleString('zh-CN',{hour12:false}).replaceAll('/','-')}function backToList(){router.push(isArchive.value && !route.query.listDate ? {path:`/tournaments/${tournamentId}/results`,query:{tab:'review',divisionId:match.value.divisionId}} : {path:`/tournaments/${tournamentId}/matches`,query:matchListQuery(route.query)})}function openSupplementPage(){router.push({path:`/tournaments/${tournamentId}/match/${matchId}/post-match`,query:{...matchSourceQuery(route.query),...(match.value.divisionId?{divisionId:match.value.divisionId}:{})}})}
function openScoreCorrection(){
  if(!isArchive.value)return ElMessage.warning('只有已归档的正式赛果可以异常纠错')
  correctionForm.value={homeScore:Number(match.value.homeScore ?? 0),awayScore:Number(match.value.awayScore ?? 0),reason:''}
  correctionVisible.value=true
}
async function submitScoreCorrection(){
  const form=correctionForm.value
  if(!Number.isInteger(Number(form.homeScore))||!Number.isInteger(Number(form.awayScore))||Number(form.homeScore)<0||Number(form.homeScore)>99||Number(form.awayScore)<0||Number(form.awayScore)>99)return ElMessage.warning('请输入0至99之间的整数比分')
  if(!String(form.reason||'').trim())return ElMessage.warning('请填写比分更正原因')
  try{
    await ElMessageBox.confirm(`将比分更正为 ${form.homeScore} : ${form.awayScore}，并保留当前归档记录。确认继续？`,'确认异常纠错',{type:'warning',confirmButtonText:'确认更正',cancelButtonText:'取消'})
    correctionSaving.value=true
    const result=await correctArchivedScore({tournamentId,matchId,homeScore:Number(form.homeScore),awayScore:Number(form.awayScore),reason:String(form.reason).trim()})
    if(!result?.success)throw new Error(result?.message||result?.error||'比分更正失败')
    match.value={...match.value,homeScore:Number(form.homeScore),awayScore:Number(form.awayScore),scoreHome:Number(form.homeScore),scoreAway:Number(form.awayScore),resultCorrectedAt:new Date().toISOString(),resultCorrectionReason:String(form.reason).trim(),resultCorrection:{...(match.value.resultCorrection||{}),reason:String(form.reason).trim(),correctedAt:new Date().toISOString(),before:{homeScore:Number(match.value.homeScore ?? 0),awayScore:Number(match.value.awayScore ?? 0)},after:{homeScore:Number(form.homeScore),awayScore:Number(form.awayScore)}}}
    correctionVisible.value=false
    ElMessage.success(result.message||'比分已更正')
  }catch(error){if(error!=='cancel'&&error!=='close')ElMessage.error(error.message||'比分更正失败')}finally{correctionSaving.value=false}
}
function saveDraft(){ElMessage.success('复核草稿已保存在当前会话，提交归档前仍可修改。')}function openReturnDialog(){returnForm.value={reason:'',fields:[]};returnVisible.value=true}
async function archiveRecord(){try{await ElMessageBox.confirm('归档后裁判现场快照永久只读，确认无误后继续。','复核通过并完成归档',{type:'warning'});saving.value=true;const result=await reviewRefereeRecord({matchId,reviewOperation:'archive',reviewNote:reviewNote.value});if(!result.success)throw new Error(result.error||result.message||'归档失败');match.value.refereeReviewStatus='archived';match.value.refereeArchivedAt=new Date().toISOString();ElMessage.success(result.message||'赛果已归档');router.replace(`/tournaments/${tournamentId}/match/${matchId}/archive`)}catch(error){if(error!=='cancel'&&error!=='close')ElMessage.error(error.message||'归档失败')}finally{saving.value=false}}
async function returnRecord(){if(!returnForm.value.reason.trim()||!returnForm.value.fields.length)return ElMessage.warning('请填写退回原因并选择允许修正的字段');try{saving.value=true;const result=await reviewRefereeRecord({matchId,reviewOperation:'return',reason:returnForm.value.reason,fields:returnForm.value.fields});if(!result.success)throw new Error(result.error||result.message||'退回失败');match.value.refereeReviewStatus='returned';returnVisible.value=false;ElMessage.success(result.message||'已退回原裁判限定修正');backToList()}catch(error){ElMessage.error(error.message||'退回失败')}finally{saving.value=false}}
async function load(){if(visualQaSnapshot)return;loading.value=true;try{const[m,t,e,teamRows]=await Promise.all([queryById('matches',matchId),queryById('tournaments',tournamentId),queryList('match_events',{where:{matchId},silent:true}),queryList('teams',{where:{tournamentId},silent:true})]);match.value=Array.isArray(m)?m[0]||{}:m||{};tournament.value=Array.isArray(t)?t[0]||{}:t||{};if(match.value.divisionId)matchDivision.value=await queryById('divisions',match.value.divisionId);events.value=mergeMatchEvents(match.value.events,e,{homeTeamId:match.value.homeTeamId,awayTeamId:match.value.awayTeamId});teams.value=teamRows||[];const teamIds=[match.value.homeTeamId,match.value.awayTeamId].filter(Boolean);const tournamentTeams=(await Promise.all(teamIds.map(teamId=>queryList('tournament_teams',{where:{_id:teamId},limit:1,silent:true})))).flat().filter(Boolean);const realTeamIds=[...new Set([...teamIds,...tournamentTeams.map(item=>item.teamId).filter(Boolean)])];const playerResults=await Promise.all(realTeamIds.flatMap(teamId=>[queryList('players',{where:{teamId},limit:1000,silent:true}),queryList('players',{where:{teamCode:teamId},limit:1000,silent:true})]));rosterPlayers.value=[...new Map(playerResults.flat().filter(Boolean).map(player=>[String(player._id||player.id||`${player.name||''}:${player.birthDate||player.birthday||''}`),player])).values()]}catch(error){ElMessage.error(error.message||'比赛复核资料加载失败')}finally{loading.value=false}}onMounted(load)
async function renderLineupCanvas(){const target=cslExportTemplate.value?.querySelector('.csl-export-page');if(!target)throw new Error('未找到首发名单模板');const html2canvas=(await import('html2canvas')).default;return html2canvas(target,{scale:2,backgroundColor:'#fff',useCORS:true,allowTaint:true,logging:false})}
async function openLineupPreview(){try{const canvas=await renderLineupCanvas();lineupPreviewImage.value=canvas.toDataURL('image/png');lineupPreviewVisible.value=true}catch(error){ElMessage.error(`首发名单预览失败：${error.message||'请重试'}`)}}
function openReportPreview(){reportTemplatePreviewVisible.value=true}
function triggerReportUpload(){reportUploadInput.value?.click()}
async function compressReportImage(file){if(!file?.type?.startsWith('image/'))return file;try{const url=URL.createObjectURL(file);const image=await new Promise((resolve,reject)=>{const value=new Image();value.onload=()=>resolve(value);value.onerror=reject;value.src=url});const maxSide=2200;const scale=Math.min(1,maxSide/Math.max(image.naturalWidth||image.width,image.naturalHeight||image.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round((image.naturalWidth||image.width)*scale));canvas.height=Math.max(1,Math.round((image.naturalHeight||image.height)*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',0.78));URL.revokeObjectURL(url);return blob?new File([blob],file.name.replace(/\.[^.]+$/,'')+'.jpg',{type:'image/jpeg',lastModified:Date.now()}):file}catch{return file}}
async function onReportFilesSelected(event){const files=Array.from(event.target?.files||[]);if(!files.length)return;if((reportFiles.value.length+files.length)>2)return ElMessage.warning('最多上传 2 份裁判报告');reportUploading.value=true;try{const added=[];for(const file of files){const optimized=await compressReportImage(file);const suffix=optimized.name.includes('.')?optimized.name.slice(optimized.name.lastIndexOf('.')):'';const result=await uploadLargeFileViaCloud(`match-reports/${matchId}/${Date.now()}-${Math.random().toString(16).slice(2)}${suffix}`,optimized,{chunkSize:32*1024});const fileId=result.fileID||result.fileId||result.url||result.data?.fileID;if(!fileId)throw new Error('上传结果缺少文件地址');added.push({name:optimized.name,size:optimized.size,sizeText:`${Math.round(optimized.size/1024)} KB`,fileId,url:await getFileUrl(fileId).catch(()=> '')})}const updated=[...reportFiles.value,...added];await updateRecord('matches',matchId,{organizerSupplementFiles:updated,organizerSupplementUpdatedAt:new Date().toISOString()});match.value={...match.value,organizerSupplementFiles:updated,organizerSupplementUpdatedAt:new Date().toISOString()};ElMessage.success('裁判报告已上传');if(reportUploadInput.value)reportUploadInput.value.value=''}catch(error){ElMessage.error(error.message||'裁判报告上传失败')}finally{reportUploading.value=false}}
async function viewReportFile(file){try{const url=file.url||await getFileUrl(file.fileId||file.fileID);if(!url)return ElMessage.warning('报告文件暂无可查看地址');window.open(url,'_blank','noopener,noreferrer')}catch(error){ElMessage.error(error.message||'报告打开失败')}}
async function downloadReportPDF(){try{const target=reportTemplateRef.value;if(!target)return ElMessage.warning('未找到报告预览内容');const pages=Array.from(target.querySelectorAll('.referee-report-page'));const html2canvas=(await import('html2canvas')).default;const {default:jsPDF}=await import('jspdf');const doc=new jsPDF({orientation:'portrait',unit:'mm',format:'a4'});const pageW=doc.internal.pageSize.getWidth(),pageH=doc.internal.pageSize.getHeight(),margin=6;for(let index=0;index<pages.length;index+=1){const canvas=await html2canvas(pages[index],{scale:2,backgroundColor:'#fff',useCORS:true,allowTaint:true,logging:false});if(index>0)doc.addPage();const ratio=Math.min((pageW-margin*2)/canvas.width,(pageH-margin*2)/canvas.height);const drawW=canvas.width*ratio,drawH=canvas.height*ratio;doc.addImage(canvas.toDataURL('image/png'),'PNG',margin+(pageW-margin*2-drawW)/2,margin+(pageH-margin*2-drawH)/2,drawW,drawH)}doc.save(`${match.value.matchDate||''}_${homeName.value||'主队'}vs${awayName.value||'客队'}_裁判员报告.pdf`.replace(/\s+/g,''));ElMessage.success('裁判员报告 PDF 已下载')}catch(error){ElMessage.error(`报告 PDF 导出失败：${error.message||'请重试'}`)}}
async function downloadLineupPDF(){try{const canvas=await renderLineupCanvas();const {default:jsPDF}=await import('jspdf');const imgData=canvas.toDataURL('image/png');const doc=new jsPDF({orientation:'portrait',unit:'mm',format:'a4'});const pageW=doc.internal.pageSize.getWidth(),pageH=doc.internal.pageSize.getHeight(),margin=6;const ratio=Math.min((pageW-margin*2)/canvas.width,(pageH-margin*2)/canvas.height);const drawW=canvas.width*ratio,drawH=canvas.height*ratio;doc.addImage(imgData,'PNG',margin+(pageW-margin*2-drawW)/2,margin+(pageH-margin*2-drawH)/2,drawW,drawH);doc.save(`${match.value.matchDate||''}_${homeName.value||'主队'}vs${awayName.value||'客队'}_中超首发名单.pdf`.replace(/\s+/g,''));ElMessage.success('中超版首发名单 PDF 已下载')}catch(error){console.error('首发名单 PDF 导出失败:',error);ElMessage.error(`首发名单 PDF 导出失败：${error.message||'请重试'}`)}}
async function exportLineupList(){await openLineupPreview()}
function exportArchivedRecord(){const lines=[['归档编号',`ARC-${match.value.matchSequence || matchId}`],['比赛',`${homeName.value} ${match.value.homeScore ?? '—'} : ${match.value.awayScore ?? '—'} ${awayName.value}`],['比赛时间',matchDateText.value],['主裁判',mainRefereeName.value],[],['事件时间','球队','事件','球员','比分'],...sortedEvents.value.map(item=>[`${item.minute}'`,item.teamName || '',eventLabel(item),item.playerName || '',item.score || ''])];const csv=lines.map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([`\uFEFF${csv}`],{type:'text/csv;charset=utf-8'}));link.download=`${match.value.matchSequence || '比赛'}-电子记录归档.csv`;link.click();URL.revokeObjectURL(link.href);ElMessage.success('已导出只读电子记录')}
function exportElectronicReport(){const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));const rows=(items,empty='暂无记录')=>items.length?items.map(item=>`<tr><td>${escapeHtml(item.minute)}′</td><td>${escapeHtml(item.teamName||'球队待定')}</td><td>${escapeHtml(eventLabel(item))}</td><td>${escapeHtml(item.playerName||'球员待定')}</td><td>${escapeHtml(item.score||'')}</td></tr>`).join(''): `<tr><td colspan="5">${empty}</td></tr>`;const lineupRows=lineupPanels.value.map(item=>`<section><h3>${escapeHtml(item.teamName)}</h3><table><tr><th>名单</th><th>号码</th><th>球衣名</th><th>球员</th><th>年龄</th><th>位置</th><th>出场次数</th><th>出场时间</th></tr>${item.players.map(player=>`<tr><td>${player.role==='starter'?'首发':'替补'}</td><td>${escapeHtml(player.jerseyNumber)}</td><td>${escapeHtml(player.jerseyName)}</td><td>${escapeHtml(player.name)}</td><td>${player.age}</td><td>${escapeHtml(player.position)}</td><td>${player.appearances}</td><td>${player.minutes}′</td></tr>`).join('')||'<tr><td colspan="8">暂无名单</td></tr>'}</table></section>`).join('');const html=`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>电子裁判报告-${escapeHtml(match.value.matchSequence||'比赛')}</title><style>body{font:14px/1.7 Arial;color:#17251c;max-width:900px;margin:32px auto;padding:0 24px}h1{font-size:26px}h2{border-bottom:1px solid #dfe7e2;padding-bottom:8px;margin-top:28px}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #e8eeea;text-align:left;padding:8px}section{padding:12px 16px;background:#f6faf7;margin:10px 0;border-radius:6px}</style><h1>电子裁判报告</h1><p>${escapeHtml(homeName.value)}　<b>${escapeHtml(match.value.homeScore??'—')} : ${escapeHtml(match.value.awayScore??'—')}</b>　${escapeHtml(awayName.value)}</p><p>场序：${escapeHtml(match.value.matchSequence||'—')}　时间：${escapeHtml(matchDateText.value)}　场地：${escapeHtml(match.value.venue||'待定')}</p><p>数据来源：${escapeHtml(reportModeLabel.value)}　主裁判：${escapeHtml(mainRefereeName.value)}</p><h2>双方首发与替补</h2>${lineupRows}<h2>进球</h2><table><tr><th>时间</th><th>球队</th><th>事件</th><th>球员</th><th>比分</th></tr>${rows(goalEvents.value)}</table><h2>换人</h2><table><tr><th>时间</th><th>球队</th><th>事件</th><th>球员</th><th>比分</th></tr>${rows(substitutionEvents.value)}</table><h2>红黄牌与停赛</h2><table><tr><th>时间</th><th>球队</th><th>事件</th><th>球员</th><th>比分</th></tr>${rows(cardEvents.value)}</table>${disciplineRows.value.length?`<h2>停赛提醒</h2><ul>${disciplineRows.value.map(item=>`<li>${escapeHtml(item.teamName)}　${escapeHtml(item.playerName)}：${escapeHtml(item.notice)}</li>`).join('')}</ul>`:''}<p>生成时间：${escapeHtml(formatDate(new Date()))}</p></html>`;const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));link.download=`${match.value.matchSequence||'比赛'}-电子裁判报告.html`;link.click();URL.revokeObjectURL(link.href);ElMessage.success('电子裁判报告已下载')}
const downloadElectronicReportHtml=exportElectronicReport
exportElectronicReport=()=>openReportPreview()
function handleArchiveAction(event){if(!isArchive.value)return;const label=event.target.closest('.archive-actions .el-button')?.textContent?.trim();if(label==='导出电子记录')exportArchivedRecord();if(label==='查看审计日志'){const rows=[['提交复核',submittedAtText.value,'裁判端电子记录已提交'],['复核通过',submittedAtText.value,'主办方复核结论：合规归档'],['完成归档',submittedAtText.value,'比赛快照与电子记录已转为只读']];if(match.value.resultCorrection)rows.push(['异常纠错',formatDate(match.value.resultCorrection.correctedAt||match.value.resultCorrectedAt),`比分更正为 ${match.value.homeScore} : ${match.value.awayScore}；${match.value.resultCorrection.reason}`]);ElMessageBox.alert(rows.map(row=>`${row[0]}　${row[1]}\n${row[2]}`).join('\n\n'),'归档审计日志',{confirmButtonText:'关闭'})}}
